package com.loja.checkout.service;

import com.loja.checkout.domain.*;
import com.loja.checkout.dto.PedidoRequest;
import com.loja.checkout.dto.ResumoResponse;
import com.loja.checkout.util.Arredondador;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class CalculadorResumo {

    public ResumoResponse calcular(PedidoRequest request) {
        // Converter itens para domínio
        List<ItemPedido> itens = converterItens(request.itens());

        // 1. Calcular subtotal dos produtos
        BigDecimal subtotalProdutos = calcularSubtotal(itens);

        // 2. Aplicar cupom (desconto nos produtos e/ou no frete)
        Cupom cupom = request.cupom() != null ? Cupom.porCodigo(request.cupom()) : null;
        BigDecimal descontoCupom = BigDecimal.ZERO;
        BigDecimal descontoFreteViaCupom = BigDecimal.ZERO;

        if (cupom != null) {
            descontoCupom = Arredondador.arredondarParaCentavos(cupom.calcularDesconto(subtotalProdutos, itens));
            descontoFreteViaCupom = Arredondador.arredondarParaCentavos(cupom.calcularDescontoNoFrete(BigDecimal.ZERO));
        }

        // 3. Calcular frete
        ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.modalidadeEntrega());
        NivelClube nivelClube = NivelClube.valueOf(request.nivelClube());
        BigDecimal pesoTotal = calcularPesoTotal(itens);
        BigDecimal freteBase = Arredondador.arredondarParaCentavos(modalidade.calcularFrete(pesoTotal));

        // Se o cliente é OURO, frete é grátis
        BigDecimal frete = nivelClube.isGratisFrete() ? BigDecimal.ZERO : freteBase;

        // Se tem cupom FRETEGRATIS, desconto do cupom é igual ao frete
        if (cupom instanceof Cupom.CupomFreteGratis) {
            descontoFreteViaCupom = frete;
            frete = BigDecimal.ZERO;
            descontoCupom = descontoFreteViaCupom;
        }

        // 4. Calcular seguro (sobre subtotal, sem desconto, sem frete)
        Regiao regiao = Regiao.valueOf(request.regiao());
        BigDecimal seguro = Arredondador.arredondarParaCentavos(regiao.calcularSeguro(subtotalProdutos));

        // 5. Calcular crédito do clube (sobre subtotal, sem desconto, sem frete)
        BigDecimal creditoProximaCompra = Arredondador.arredondarParaCentavos(nivelClube.calcularCredito(subtotalProdutos));

        // 6. Calcular total antes do ajuste de pagamento
        BigDecimal totalAntesPagamento = subtotalProdutos
            .subtract(descontoCupom)
            .add(frete)
            .add(seguro);
        totalAntesPagamento = Arredondador.arredondarParaCentavos(totalAntesPagamento);

        // 7. Aplicar ajuste de pagamento
        FormaPagamento formaPagamento = FormaPagamento.valueOf(request.formaPagamento());
        int parcelas = request.parcelas() == null ? 1 : request.parcelas();

        BigDecimal ajustePagamento;
        BigDecimal totalComAjuste;
        BigDecimal valorParcela;

        if (formaPagamento == FormaPagamento.PIX) {
            // PIX: 5% de desconto no total
            BigDecimal desconto = Arredondador.arredondarParaCentavos(totalAntesPagamento.multiply(BigDecimal.valueOf(0.05)));
            ajustePagamento = desconto.negate();
            totalComAjuste = Arredondador.arredondarParaCentavos(totalAntesPagamento.subtract(desconto));
            valorParcela = totalComAjuste;
        } else if (formaPagamento == FormaPagamento.BOLETO) {
            // BOLETO: taxa de 3,49
            ajustePagamento = BigDecimal.valueOf(3.49);
            totalComAjuste = Arredondador.arredondarParaCentavos(totalAntesPagamento.add(ajustePagamento));
            valorParcela = totalComAjuste;
        } else if (formaPagamento == FormaPagamento.CARTAO) {
            if (parcelas <= 3) {
                // Sem juros
                ajustePagamento = BigDecimal.ZERO;
                totalComAjuste = totalAntesPagamento;
                valorParcela = Arredondador.arredondarParaCentavos(totalComAjuste.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
            } else {
                // Com juros: tabela Price
                BigDecimal taxaMensal = BigDecimal.valueOf(0.0199);
                BigDecimal um = BigDecimal.ONE;
                BigDecimal fator = um.add(taxaMensal);
                BigDecimal potencia = fator.pow(parcelas);
                BigDecimal divisor = potencia.subtract(um);

                valorParcela = totalAntesPagamento
                    .multiply(taxaMensal)
                    .multiply(potencia)
                    .divide(divisor, 10, java.math.RoundingMode.HALF_EVEN);
                valorParcela = Arredondador.arredondarParaCentavos(valorParcela);

                totalComAjuste = Arredondador.arredondarParaCentavos(valorParcela.multiply(BigDecimal.valueOf(parcelas)));
                ajustePagamento = totalComAjuste.subtract(totalAntesPagamento);
                ajustePagamento = Arredondador.arredondarParaCentavos(ajustePagamento);
            }
        } else {
            ajustePagamento = BigDecimal.ZERO;
            totalComAjuste = totalAntesPagamento;
            valorParcela = Arredondador.arredondarParaCentavos(totalComAjuste.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
        }

        boolean temBrinde = nivelClube.temBrinde(subtotalProdutos);

        return new ResumoResponse(
            subtotalProdutos,
            descontoCupom,
            frete,
            modalidade.getPrazo(),
            seguro,
            ajustePagamento,
            totalComAjuste,
            parcelas,
            valorParcela,
            creditoProximaCompra,
            temBrinde
        );
    }

    private List<ItemPedido> converterItens(List<PedidoRequest.Item> itens) {
        return itens.stream()
            .map(item -> new ItemPedido(
                item.nome(),
                new BigDecimal(item.precoUnitario().toString()),
                item.quantidade(),
                new BigDecimal(item.pesoKg().toString())
            ))
            .toList();
    }

    private BigDecimal calcularSubtotal(List<ItemPedido> itens) {
        BigDecimal subtotal = BigDecimal.ZERO;
        for (ItemPedido item : itens) {
            BigDecimal quantidade = BigDecimal.valueOf(item.quantidade());
            BigDecimal linhaTotal = item.precoUnitario().multiply(quantidade);
            subtotal = subtotal.add(linhaTotal);
        }
        return Arredondador.arredondarParaCentavos(subtotal);
    }

    private BigDecimal calcularPesoTotal(List<ItemPedido> itens) {
        BigDecimal pesoTotal = BigDecimal.ZERO;
        for (ItemPedido item : itens) {
            BigDecimal quantidade = BigDecimal.valueOf(item.quantidade());
            BigDecimal pesoLinha = item.pesoKg().multiply(quantidade);
            pesoTotal = pesoTotal.add(pesoLinha);
        }
        return pesoTotal;
    }
}

