2	
3	import com.loja.checkout.domain.*;
4	import com.loja.checkout.dto.PedidoRequest;
5	import java.math.BigDecimal;
6	import java.util.Arrays;
7	
8	public class ValidadorPedido {
9	    public String validar(PedidoRequest request) {
10	        // 1. Validar itens
11	        if (request.itens() == null || request.itens().isEmpty()) {
12	            return "PEDIDO_INVALIDO";
13	        }
14	        for (var item : request.itens()) {
15	            if (item.precoUnitario() == null || item.quantidade() == null || item.pesoKg() == null) {
16	                return "PEDIDO_INVALIDO";
17	            }
18	            BigDecimal preco = new BigDecimal(item.precoUnitario().toString());
19	            BigDecimal peso = new BigDecimal(item.pesoKg().toString());
20	            if (preco.compareTo(BigDecimal.ZERO) <= 0 ||
21	                item.quantidade() <= 0 ||
22	                peso.compareTo(BigDecimal.ZERO) < 0) {
23	                return "PEDIDO_INVALIDO";
24	            }
25	        }
26	
27	        // 2. Validar nível do clube
28	        if (request.nivelClube() == null) {
29	            return "NIVEL_CLUBE_INVALIDO";
30	        }
31	        try {
32	            NivelClube.valueOf(request.nivelClube());
33	        } catch (IllegalArgumentException e) {
34	            return "NIVEL_CLUBE_INVALIDO";
35	        }
36	
37	        // 3. Validar região
38	        if (request.regiao() == null) {
39	            return "REGIAO_INVALIDA";
40	        }
41	        try {
42	            Regiao.valueOf(request.regiao());
43	        } catch (IllegalArgumentException e) {
44	            return "REGIAO_INVALIDA";
45	        }
46	
47	        // 4. Validar modalidade de entrega
48	        if (request.modalidadeEntrega() == null) {
49	            return "MODALIDADE_INVALIDA";
50	        }
51	        ModalidadeEntrega modalidade;
52	        try {
53	            modalidade = ModalidadeEntrega.valueOf(request.modalidadeEntrega());
54	        } catch (IllegalArgumentException e) {
55	            return "MODALIDADE_INVALIDA";
56	        }
57	
58	        // 5. Validar se modalidade atende o pedido
59	        BigDecimal pesoTotal = BigDecimal.ZERO;
60	        for (var item : request.itens()) {
61	            BigDecimal peso = new BigDecimal(item.pesoKg().toString());
62	            BigDecimal quantidade = new BigDecimal(item.quantidade());
63	            pesoTotal = pesoTotal.add(peso.multiply(quantidade));
64	        }
65	        if (!modalidade.isDisponivelPara(pesoTotal)) {
66	            return "MODALIDADE_INDISPONIVEL";
67	        }
68	
69	        // 6. Validar cupom
70	        if (request.cupom() != null) {
71	            Cupom cupom = Cupom.porCodigo(request.cupom());
72	            if (cupom == null) {
73	                return "CUPOM_INVALIDO";
74	            }
75	
76	            // 7. Validar se cupom é aplicável
77	            BigDecimal subtotal = calcularSubtotal(request.itens());
78	            java.util.List<ItemPedido> itens = converterItens(request.itens());
79	            if (!cupom.ehValido(subtotal, itens)) {
80	                return "CUPOM_NAO_APLICAVEL";
81	            }
82	        }
83	
84	        // 8. Validar forma de pagamento
85	        if (request.formaPagamento() == null) {
86	            return "FORMA_PAGAMENTO_INVALIDA";
87	        }
88	        FormaPagamento formaPagamento;
89	        try {
90	            formaPagamento = FormaPagamento.valueOf(request.formaPagamento());
91	        } catch (IllegalArgumentException e) {
92	            return "FORMA_PAGAMENTO_INVALIDA";
93	        }
94	
95	        // 9. Validar número de parcelas
96	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
97	        if (!formaPagamento.isParcelavelEm(parcelas)) {
98	            return "PARCELAMENTO_INVALIDO";
99	        }
100	
101	        // 10. Validar se forma de pagamento atende o pedido (boleto acima de 1000)
102	        BigDecimal subtotal2 = calcularSubtotal(request.itens());
103	        if (!formaPagamento.ehDisponivelPara(subtotal2)) {
104	            return "FORMA_PAGAMENTO_INDISPONIVEL";
105	        }
106	
107	        return null;
108	    }
109	
110	    private BigDecimal calcularSubtotal(java.util.List<PedidoRequest.Item> itens) {
111	        BigDecimal subtotal = BigDecimal.ZERO;
112	        for (var item : itens) {
113	            BigDecimal preco = new BigDecimal(item.precoUnitario().toString());
114	            BigDecimal quantidade = new BigDecimal(item.quantidade());
115	            subtotal = subtotal.add(preco.multiply(quantidade));
116	        }
117	        return subtotal;
118	    }
119	
120	    private java.util.List<ItemPedido> converterItens(java.util.List<PedidoRequest.Item> itens) {
121	        return itens.stream()
122	            .map(item -> new ItemPedido(
123	                item.nome(),
124	                new BigDecimal(item.precoUnitario().toString()),
125	                item.quantidade(),
126	                new BigDecimal(item.pesoKg().toString())
127	            ))
128	            .toList();
129	    }
130	}
