package com.loja.checkout.domain;

import java.math.BigDecimal;

public enum FormaPagamento {
    PIX(true, 1, 1, true),
    CARTAO(false, 1, 12, false),
    BOLETO(true, 1, 1, false);

    private final boolean ehAvista;
    private final int minParcelas;
    private final int maxParcelas;
    private final boolean temDesconto;

    FormaPagamento(boolean ehAvista, int minParcelas, int maxParcelas, boolean temDesconto) {
        this.ehAvista = ehAvista;
        this.minParcelas = minParcelas;
        this.maxParcelas = maxParcelas;
        this.temDesconto = temDesconto;
    }

    public boolean isParcelavelEm(int parcelas) {
        return parcelas >= minParcelas && parcelas <= maxParcelas;
    }

    public BigDecimal calcularAjuste(BigDecimal total, int parcelas) {
        if (this == PIX) {
            return total.multiply(BigDecimal.valueOf(-0.05));
        }
        if (this == BOLETO) {
            return BigDecimal.valueOf(3.49);
        }
        if (this == CARTAO) {
            if (parcelas <= 3) {
                return BigDecimal.ZERO;
            }
            BigDecimal taxaMensal = BigDecimal.valueOf(0.0199);
            BigDecimal fator = BigDecimal.ONE.add(taxaMensal).pow(parcelas);
            BigDecimal divisor = fator.subtract(BigDecimal.ONE);
            return total.multiply(taxaMensal).multiply(fator).divide(divisor, 10, java.math.RoundingMode.HALF_EVEN);
        }
        return BigDecimal.ZERO;
    }

    public boolean ehDisponivelPara(BigDecimal total) {
        if (this == BOLETO) {
            return total.compareTo(BigDecimal.valueOf(1000)) <= 0;
        }
        return true;
    }
}

