            BigDecimal pesoLinha = item.pesoKg().multiply(quantidade);
            pesoTotal = pesoTotal.add(pesoLinha);
        }
        return pesoTotal;
    }

    record AjusteParcelas(BigDecimal ajuste, BigDecimal total, BigDecimal valorParcela) {
    }
